import { useState } from "react";

import { formatClientError, m1Fetch } from "../lib/m1-client";
import { FormError, FormStatus, M1Layout } from "./m1-layout";

type InvitationCreated = {
  deliveryPending?: boolean;
  email: string;
  expiresAt: number;
  id: string;
  token: string;
};

export function InviteAdminPage() {
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string>();
  const [created, setCreated] = useState<InvitationCreated>();

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(undefined);
    setIsPending(true);
    try {
      const invitation = await m1Fetch<InvitationCreated>("/invitations", {
        body: JSON.stringify({ email, name: name || undefined }),
        method: "POST",
      });
      setCreated(invitation);
    } catch (submitError) {
      setError(formatClientError(submitError));
    } finally {
      setIsPending(false);
    }
